const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Rectangle([120.8, 30.7, 122.1, 31.8]);
  const startDate1 = '2020-02-10';
  const endDate1 = '2020-02-25';
  const startDate2 = '2020-04-20';
  const endDate2 = '2020-05-12';

  const band = 'tropospheric_NO2_column_number_density';
  const qaBand = 'qa_value';
  const collectionName = 'COPERNICUS/S5P/OFFL/L3_NO2';

  // Function to process data for a given period
  function getMeanNO2(startDate, endDate) {
    const collection = ee.ImageCollection(collectionName)
      .filterBounds(shanghai)
      .filterDate(startDate, endDate)
      .select([band, qaBand]);

    const imageCount = collection.size().getInfo();
    if (imageCount === 0) {
      return {
        mean: null,
        count: 0,
        pixelCount: 0,
        error: 'C1'
      };
    }

    // Use a QA filter recommended for S5P NO2 data (>0.75)
    const maskedCollection = collection.map(function(image) {
      const qa = image.select(qaBand);
      const mask = qa.gt(0.75);
      return image.updateMask(mask);
    });

    const meanImage = maskedCollection.select(band).mean();

    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: shanghai,
      scale: 3000,
      maxPixels: 1e9
    });

    return {
      mean: stats.get(band + '_mean').getInfo(),
      count: imageCount,
      pixelCount: stats.get(band + '_count').getInfo()
    };
  }

  // 2. Data Acquisition & Processing
  const period1 = getMeanNO2(startDate1, endDate1);
  const period2 = getMeanNO2(startDate2, endDate2);

  // 3. Validation and Output
  if (period1.error === 'C1' || period2.error === 'C1') {
    console.log(`Period 1 (${startDate1} to ${endDate1}) Image Count: ${period1.count || 0}`);
    console.log(`Period 2 (${startDate2} to ${endDate2}) Image Count: ${period2.count || 0}`);
    console.log("Evidence: One or both periods had no images.");
    console.log("C1");
    return;
  }

  console.log(`Period 1 (${startDate1} to ${endDate1}) Image Count: ${period1.count}`);
  console.log(`Period 2 (${startDate2} to ${endDate2}) Image Count: ${period2.count}`);

  if (period1.pixelCount === 0 || period2.pixelCount === 0) {
    console.log(`Period 1 Valid Pixels: ${period1.pixelCount}`);
    console.log(`Period 2 Valid Pixels: ${period2.pixelCount}`);
    console.log("Evidence: No valid pixels found after quality masking for at least one period.");
    console.log("C2");
    return;
  }

  const mean1 = period1.mean;
  const mean2 = period2.mean;

  console.log(`Period 1 Mean NO2 (mol/m^2): ${mean1 ? mean1.toExponential(4) : 'N/A'}`);
  console.log(`Period 1 Valid Pixels: ${period1.pixelCount}`);
  console.log(`Period 2 Mean NO2 (mol/m^2): ${mean2 ? mean2.toExponential(4) : 'N/A'}`);
  console.log(`Period 2 Valid Pixels: ${period2.pixelCount}`);

  if (mean1 === null || mean2 === null) {
    console.log("Evidence: Could not calculate mean value for one or both periods.");
    console.log("C3");
    return;
  }

  // 4. Final Answer
  if (mean2 > mean1) {
    console.log("Evidence: Mean NO2 level increased from the first period to the second.");
    console.log("A");
  } else {
    console.log("Evidence: Mean NO2 level did not increase from the first period to the second.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
